export default "/* @recourse-software/knowdrive-widgets — canonical design-contract widgets (v1).\n   Token-driven: every value references a theme token so widgets are theme- and\n   mode-responsive. No color/geometry literals (allowed: #fff on accent bg, 999px\n   pill radius, fixed border widths, component widths, color-mix). Realizes\n   design-contract §2.1 + GC5/GC16/GC17. Consume by concatenating this file into\n   an app's constructable shadow stylesheet BEFORE the app's own bundle.css. */\n\n/* ── Text link (§2.1 system primitive) ─ */\n.link { color: var(--accent-purple); text-decoration: none; cursor: pointer; }\n.link:hover { text-decoration: underline; }\n\n/* ── Inline alert bar (GC11) — subtle tinted surface + accent left-rule ─ */\n.alert {\n  padding: var(--space-2) var(--space-3);\n  border-left: 3px solid var(--border-base);\n  border-radius: var(--radius-sm);\n  font-size: var(--text-base);\n}\n.alert-danger  { background: var(--surface-danger-subtle); border-left-color: var(--accent-red);   color: var(--accent-red); }\n.alert-success { background: var(--surface-success);        border-left-color: var(--accent-green); color: var(--accent-green); }\n.alert-info    { background: var(--brand-bg);               border-left-color: var(--accent-purple); color: var(--accent-strong); }\n\n/* ── Empty state ─ */\n.empty-state {\n  padding: var(--space-5);\n  text-align: center;\n  color: var(--text-secondary);\n  background: var(--bg-surface);\n  border-radius: var(--radius-md);\n}\n\n/* ── Panel / titled section (GC17) ─ */\n.panel {\n  display: flex; flex-direction: column; gap: var(--space-2);\n  padding: var(--space-4);\n  border: 1px solid var(--border-base);\n  border-radius: var(--radius-md);\n}\n.panel > h3 { margin: 0 0 var(--space-1); font-size: var(--text-md); color: var(--text-heading); }\n\n/* ── Event timeline (GC10) — vertical rail + dots chronology ─ */\n.timeline { display: flex; flex-direction: column; gap: var(--space-2); }\n.timeline > .tl-item {\n  position: relative;\n  display: flex; flex-direction: column; gap: var(--space-1);\n  padding: var(--space-2) var(--space-3);\n  border-left: 2px solid var(--border-base);\n  font-size: var(--text-sm);\n}\n.timeline > .tl-item::before {\n  content: \"\"; position: absolute; left: -5px; top: var(--space-3);\n  width: 8px; height: 8px; border-radius: 999px; background: var(--accent-purple);\n}\n.tl-event { color: var(--text-heading); }\n.tl-actor { color: var(--text-secondary); font-size: var(--text-sm); }\n\n/* ── Shared utilities ─ */\n.muted { color: var(--text-secondary); font-size: var(--text-base); }\n.mono-id {\n  font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);\n  font-weight: 600; color: var(--text-heading);\n}\n\n/* ── Row action menu (GC3) — kebab trigger + popover of row actions ─ */\n.row-actions { position: relative; display: inline-block; }\n.row-actions-trigger {\n  background: transparent; border: 1px solid transparent;\n  border-radius: var(--radius-sm); cursor: pointer;\n  padding: var(--space-1) var(--space-2); font-size: var(--text-lg); line-height: 1;\n  color: var(--text-muted);\n}\n.row-actions-trigger:hover { background: var(--surface-hover); }\n.row-actions-menu {\n  position: absolute; right: 0; top: 100%; z-index: 20; min-width: 9rem;\n  display: flex; flex-direction: column;\n  padding: var(--space-1);\n  background: var(--bg-base);\n  border: 1px solid var(--border-base);\n  border-radius: var(--radius-md);\n  box-shadow: var(--elev-modal);\n}\n.row-actions-item {\n  text-align: left; background: transparent; border: 0;\n  padding: var(--space-2) var(--space-3); border-radius: var(--radius-sm);\n  font: inherit; color: var(--text-heading); cursor: pointer;\n}\n.row-actions-item:hover { background: var(--surface-hover); }\n.row-actions-item.danger { color: var(--accent-red); }\n\n/* ── Card (§2.1) ─────────────────────────────────────── */\n.card {\n  background: var(--bg-base);\n  border: 1px solid var(--border-base);\n  border-radius: var(--radius-lg);\n}\n.card.pad { padding: var(--space-4) var(--space-5); }\n.ctitle { font-weight: 800; color: var(--text-heading); }\n\n/* ── Chip / status badge (§2.1) — 5 tones + leading glyph ─ */\n.chip {\n  display: inline-flex;\n  align-items: center;\n  gap: var(--space-1);\n  padding: var(--space-1) var(--space-2);\n  border-radius: 999px;\n  font-size: var(--text-xs);\n  font-weight: 700;\n  text-transform: capitalize;\n}\n.chip::before { content: \"\\25CF\"; font-size: 0.85em; line-height: 1; }  /* filled dot */\n.chip.green  { background: var(--surface-success); color: var(--accent-green); }\n.chip.amber  { background: var(--amber-light); color: var(--amber); }\n.chip.red    { background: var(--surface-danger-subtle); color: var(--accent-red); }\n.chip.violet { background: var(--brand-bg); color: var(--accent-strong); }\n.chip.gray   { background: var(--surface-hover); color: var(--text-muted); }\n.chip.gray::before { content: \"\\25CC\"; }  /* hollow dot (idle) */\n\n/* ── Chip option button (§2.1) — selectable filter/option pill ─ */\n.chipbtn {\n  background: var(--bg-base);\n  border: 1px solid var(--border-base);\n  color: var(--text-muted);\n  padding: var(--space-1) var(--space-3);\n  border-radius: var(--radius-md);\n  font-family: inherit;\n  font-size: var(--text-sm);\n  cursor: pointer;\n}\n.chipbtn.active {\n  background: var(--brand-bg);\n  border-color: var(--accent-purple);\n  color: var(--accent-strong);\n}\n\n/* ── Text input + field label + field group (§2.1 / GC17) ─ */\n.input {\n  background: var(--bg-base);\n  border: 1px solid var(--border-base);\n  color: var(--text-heading);\n  padding: var(--space-2) var(--space-3);\n  border-radius: var(--radius-md);\n  font: inherit;\n}\n.input:focus {\n  outline: none;\n  border-color: var(--accent-purple);\n  box-shadow: var(--focus-ring);\n}\n.flabel { color: var(--text-muted); font-size: var(--text-base); font-weight: 500; }\n.field { display: flex; flex-direction: column; gap: var(--space-1); }\n.field.error .input { border-color: var(--accent-red); }\n/* .input also styles <select> and <input type=number|search>. Checkbox gets its own\n   accent treatment (a boxed .input would render a padded box, not a checkmark). */\n.checkbox { accent-color: var(--accent-purple); width: 1rem; height: 1rem; cursor: pointer; }\n\n/* ── Button family (§2.1 status-card button tones) ─ */\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: var(--space-1);\n  padding: var(--space-2) var(--space-4);\n  border: 1px solid transparent;\n  border-radius: var(--radius-md);\n  font: inherit;\n  font-weight: 700;\n  cursor: pointer;\n}\n.btn:disabled { opacity: 0.6; cursor: not-allowed; }\n.btn-primary { background: var(--accent-purple); color: #fff; box-shadow: var(--elev-brand-btn); }\n.btn-dark    { background: var(--text-heading); color: #fff; }\n.btn-ghost   { background: var(--bg-base); border-color: var(--border-base); color: var(--text-heading); }\n.btn-danger  { background: var(--accent-red); color: #fff; }\n.btn-dghost  { background: var(--bg-base); color: var(--accent-red); border-color: color-mix(in srgb, var(--accent-red) 30%, transparent); }\n.btn-ghost:hover:not(:disabled),\n.btn-dghost:hover:not(:disabled) { background: var(--surface-hover); }\n\n/* ── Data table (§2.1) — header per the guide: uppercase, letter-spaced, muted\n   text on a subtle page band (not a heading-color fill). Present a table inside\n   a .card (the container motif): .card:has(> .data-table) clips to the radius. ─ */\n.data-table { width: 100%; border-collapse: collapse; font-size: var(--text-md); }\n.data-table th,\n.data-table td {\n  text-align: left;\n  padding: var(--space-2) var(--space-3);\n  border-bottom: 1px solid var(--border-base);\n}\n.data-table th {\n  font-weight: 700;\n  font-size: var(--text-xs);\n  text-transform: uppercase;\n  letter-spacing: 0.07em;\n  color: var(--text-muted);\n  background: var(--bg-surface);\n}\n.data-table tbody tr { cursor: pointer; }\n.data-table tbody tr:hover { background: var(--surface-hover); }\n.data-table tbody tr:last-child td { border-bottom: 0; }  /* clean edge inside a card */\n.card:has(> .data-table) { overflow: hidden; }             /* clip the table to the card radius */\n\n/* ── Slide-in drawer (GC5) ─ */\n.drawer-backdrop { position: fixed; inset: 0; background: var(--scrim); z-index: 50; }\n.drawer {\n  position: fixed; top: 0; right: 0; bottom: 0;\n  width: min(560px, 100%);\n  background: var(--bg-base);\n  border-left: 1px solid var(--border-base);\n  box-shadow: -4px 0 24px var(--elev-color-lg);\n  z-index: 51;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n}\n.drawer > header {\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  gap: var(--space-1);\n  padding: var(--space-4) var(--space-5);\n  border-bottom: 1px solid var(--border-base);\n}\n.drawer > header .close {\n  position: absolute; top: var(--space-3); right: var(--space-3);\n  width: var(--space-6); height: var(--space-6);\n  border: 0; border-radius: var(--radius-sm);\n  background: transparent; font-size: var(--text-xl); line-height: 1; cursor: pointer;\n}\n.drawer > header .close:hover { background: var(--surface-hover); }\n.drawer > section { display: flex; flex-direction: column; gap: var(--space-5); padding: var(--space-5); }\n\n/* ── Destructive controls (GC16) ─ */\n.danger-zone {\n  display: flex; flex-direction: column; gap: var(--space-2);\n  padding: var(--space-4);\n  border: 1px solid color-mix(in srgb, var(--accent-red) 30%, transparent);\n  border-radius: var(--radius-md);\n  background: var(--surface-danger-subtle);\n}\n.danger-zone h3 { margin: 0; font-size: var(--text-md); color: var(--accent-red); }\n.danger-zone .btn { align-self: flex-start; }  /* buttons stay compact, not full-width in the column flex */\n.confirm-dialog {\n  position: fixed; inset: 0; background: var(--scrim);\n  display: flex; align-items: center; justify-content: center; z-index: 60;\n}\n.confirm-dialog > div {\n  background: var(--bg-base);\n  border-radius: var(--radius-md);\n  padding: var(--space-5);\n  max-width: 28rem;\n  display: flex; flex-direction: column; gap: var(--space-4);\n  box-shadow: var(--elev-modal);\n}\n.confirm-dialog .actions { display: flex; justify-content: flex-end; gap: var(--space-2); }\n\n/* ── Auth card (§2.4 \"Auth card shell\", adapted A4/D1/D3/E4 — §2.6; ledger §4.1) ─\n   Brand-neutral: the host supplies the logo in .auth-card-logo (currentColor = accent). */\n.auth-card {\n  box-sizing: border-box;\n  width: 100%;\n  max-width: 22rem;\n  margin: 0 auto;\n  display: flex; flex-direction: column;\n  padding: var(--space-5);\n  background: var(--bg-base);\n  border: 1px solid var(--border-base);\n  border-radius: var(--radius-lg);\n  box-shadow: var(--elev-dropdown);\n}\n.auth-card-logo {\n  display: flex; justify-content: center;\n  margin-bottom: var(--space-4);\n  color: var(--accent-purple);\n}\n.auth-card-logo img,\n.auth-card-logo svg { height: 2rem; width: auto; max-width: 100%; }\n.auth-card-title {\n  margin: 0;\n  text-align: center;\n  font-size: var(--text-lg);\n  font-weight: 800;\n  letter-spacing: -0.01em;\n  line-height: var(--leading-tight);\n  color: var(--text-heading);\n}\n.auth-card-sub {\n  margin: var(--space-1) 0 0;\n  text-align: center;\n  font-size: var(--text-sm);\n  line-height: var(--leading-normal);\n  color: var(--text-secondary);\n}\n.auth-card-body {\n  display: flex; flex-direction: column; gap: var(--space-4);\n  margin-top: var(--space-5);\n}\n.auth-card-body > .btn { box-sizing: border-box; width: 100%; }\n.auth-card-foot {\n  margin: var(--space-4) 0 0;\n  text-align: center;\n  font-size: var(--text-sm);\n  color: var(--text-secondary);\n}\n\n/* ── Inline form error (§2.4 \"Inline form error\", adapted — §2.6) ─ */\n.form-error { margin: 0; font-size: var(--text-xs); font-weight: 600; color: var(--accent-red); }\n\n\n/* ── Confirmation panel (§2.4 \"Confirmation / check your inbox panel\", D2/D4 adapted — §2.6) ─ */\n.confirm-panel {\n  display: flex; flex-direction: column; align-items: center; gap: var(--space-2);\n  text-align: center;\n}\n.confirm-panel-medallion {\n  display: flex; align-items: center; justify-content: center;\n  width: 3.75rem; height: 3.75rem;\n  margin-bottom: var(--space-2);\n  border-radius: var(--radius-lg);\n  background: var(--brand-bg);\n  color: var(--accent-purple);\n}\n.confirm-panel-medallion > svg { width: 50%; height: 50%; }\n.confirm-panel-title {\n  margin: 0;\n  font-size: var(--text-lg); font-weight: 800; letter-spacing: -0.01em;\n  line-height: var(--leading-tight);\n  color: var(--text-heading);\n}\n.confirm-panel-body {\n  margin: 0;\n  font-size: var(--text-base); line-height: var(--leading-normal);\n  color: var(--text-secondary);\n}\n.confirm-panel-body strong { font-weight: 700; color: var(--text-heading); }\n.confirm-panel > .btn { align-self: stretch; margin-top: var(--space-3); }\n.confirm-panel-success .confirm-panel-medallion {\n  border-radius: 999px;\n  background: var(--surface-success);\n  color: var(--accent-green);\n}\n\n/* ── Invitation header (§2.4 \"Invitation-accept header\", E4 adapted — §2.6) ─ */\n.invite-header {\n  display: flex; flex-direction: column; align-items: center; gap: var(--space-3);\n  text-align: center;\n}\n.invite-header-avatar {\n  display: flex; align-items: center; justify-content: center;\n  width: 2.75rem; height: 2.75rem;\n  overflow: hidden;\n  border-radius: var(--radius-md);\n  background: var(--accent-purple);\n  color: #fff;\n  font-size: var(--text-lg); font-weight: 800; line-height: 1;\n  box-shadow: 0 0 0 2px var(--bg-base);\n}\n.invite-header-avatar > img { width: 100%; height: 100%; object-fit: cover; }\n.invite-header-text {\n  display: flex; flex-direction: column; gap: var(--space-2);\n  font-size: var(--text-sm); line-height: var(--leading-normal);\n  color: var(--text-secondary);\n}\n.invite-header-text > p { margin: 0; }\n.invite-header-text strong { font-weight: 700; color: var(--text-heading); }\n\n/* ── Pager (Gap Register PW1 — no design-source mockup; adapted from knowdrive-admin's\n   layout-only .pager, property-compatible with it — §2.6) ─ */\n.pager {\n  display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-4);\n  margin-top: var(--space-4);\n}\n.pager-info { font-size: var(--text-sm); color: var(--text-secondary); }\n.pager-btns { display: flex; gap: var(--space-2); margin-left: auto; }\n\n/* ── Password field (§2.4 \"Password field\", A4/D3 adapted — §2.6) — <PasswordField> ─ */\n.pw-field { display: flex; flex-direction: column; gap: var(--space-4); }\n.pw-input { position: relative; display: flex; }\n.pw-input > .input {\n  box-sizing: border-box;\n  flex: 1; min-width: 0; width: 100%;\n  padding-right: var(--space-7);\n}\n.pw-field .input[type=\"password\"] { letter-spacing: 0.125em; }\n.pw-reveal {\n  position: absolute; top: 50%; right: var(--space-2); transform: translateY(-50%);\n  display: inline-flex; align-items: center; justify-content: center;\n  width: 2rem; height: 2rem; padding: 0;\n  border: 0; border-radius: var(--radius-sm);\n  background: transparent; color: var(--text-faint); cursor: pointer;\n}\n.pw-reveal:hover:not(:disabled) { background: var(--surface-hover); color: var(--text-heading); }\n.pw-reveal:focus-visible { outline: none; box-shadow: var(--focus-ring); }\n.pw-reveal:disabled { cursor: not-allowed; opacity: 0.6; }\n.pw-strength { display: flex; gap: var(--space-1); margin-top: var(--space-1); }\n.pw-strength-seg { flex: 1; height: 5px; border-radius: 999px; background: var(--border-base); }\n.pw-strength[data-score=\"1\"] .pw-strength-seg:nth-child(-n+1) { background: var(--accent-red); }\n.pw-strength[data-score=\"2\"] .pw-strength-seg:nth-child(-n+2) { background: var(--amber); }\n.pw-strength[data-score=\"3\"] .pw-strength-seg:nth-child(-n+3) { background: var(--accent-green); }\n.pw-strength[data-score=\"4\"] .pw-strength-seg { background: var(--accent-green); }\n.pw-reqs {\n  display: flex; flex-direction: column; gap: var(--space-1);\n  margin: var(--space-1) 0 0; padding: 0; list-style: none;\n}\n.pw-req { display: flex; align-items: center; gap: var(--space-2); font-size: var(--text-xs); color: var(--text-muted); }\n.pw-req-glyph { flex: none; width: 1em; text-align: center; }\n.pw-req-glyph::before { content: \"\\25CB\"; color: var(--text-faint); }\n.pw-req.met .pw-req-glyph::before { content: \"\\2713\"; font-weight: 700; color: var(--accent-green); }\n\n.pw-match { margin: 0; font-size: var(--text-xs); font-weight: 600; }\n.pw-match.met { color: var(--accent-green); }\n.pw-match.unmet { color: var(--accent-red); }\n.field.pw-confirm-ok .input { border-color: var(--border-success); }\n\n/* ── Visually-hidden utility (shared; token-free) — text for assistive tech only ─ */\n.sr-only {\n  position: absolute;\n  width: 1px; height: 1px;\n  padding: 0; margin: -1px;\n  overflow: hidden;\n  clip: rect(0, 0, 0, 0);\n  white-space: nowrap;\n  border: 0;\n}\n\n/* ── Status card (§2.4 \"Error / status card\", §07 adapted — §2.6) — <StatusCard> ─ */\n.status-card {\n  box-sizing: border-box;\n  display: flex; flex-direction: column; gap: var(--space-3);\n  padding: var(--space-4) var(--space-5);\n  background: var(--bg-base);\n  border: 1px solid var(--border-base);\n  border-radius: var(--radius-lg);\n  box-shadow: var(--elev-card);\n  text-align: left;\n}\n.status-card-head { display: flex; align-items: center; gap: var(--space-3); }\n.status-card-icon {\n  flex: none;\n  display: inline-flex; align-items: center; justify-content: center;\n  width: 2.125rem; height: 2.125rem;\n  border-radius: var(--radius-md);\n}\n.status-card-title { font-size: var(--text-md); font-weight: 700; line-height: var(--leading-snug); color: var(--text-heading); }\n.status-card-body { font-size: var(--text-sm); line-height: var(--leading-normal); color: var(--text-secondary); }\n.status-card-body strong { font-weight: 700; color: var(--text-heading); }\n.status-card-actions { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2) var(--space-3); }\n.status-card-security .status-card-icon { background: var(--surface-secure); color: var(--secure); }\n.status-card-time .status-card-icon { background: var(--amber-light); color: var(--amber); }\n.status-card-info .status-card-icon { background: var(--surface-info); color: var(--accent-info); }\n.status-card-ok .status-card-icon { background: var(--surface-success); color: var(--accent-green); }\n.status-card-neutral .status-card-icon { background: var(--surface-hover); color: var(--text-muted); }\n\n/* ── Choice list (§2.4 \"Choice / option list\", Auth Flows C1/E1 adapted — §2.6) — <ChoiceList> ─ */\n.choice-list { display: flex; flex-direction: column; gap: var(--space-2); }\n.choice {\n  display: flex; align-items: center; justify-content: space-between; gap: var(--space-3);\n  padding: var(--space-3) var(--space-4);\n  border: 1.5px solid var(--border-base);\n  border-radius: var(--radius-md);\n  background: var(--bg-base);\n  cursor: pointer;\n}\n.choice:hover { background: var(--surface-hover); }\n.choice.selected { border-color: var(--accent-purple); background: var(--bg-page); }\n.choice.disabled { cursor: not-allowed; opacity: 0.6; }\n.choice-text { display: flex; flex-direction: column; gap: var(--space-1); min-width: 0; }\n.choice-title { font-size: var(--text-sm); font-weight: 700; color: var(--text-heading); }\n.choice-desc { font-size: var(--text-xs); font-weight: 500; color: var(--text-muted); }\n.choice-radio {\n  flex: none; appearance: none; margin: 0; box-sizing: border-box;\n  width: 1.125rem; height: 1.125rem; border-radius: 50%;\n  border: 1.5px solid var(--text-faint);\n  background: var(--bg-base);\n  cursor: inherit;\n}\n.choice-radio:checked { border: 5px solid var(--accent-purple); }\n.choice-radio:focus-visible { outline: none; box-shadow: var(--focus-ring); }\n\n/* ── Tab strip (GC6, partial — §2.6) — <Tabs> ─\n   Console #dTabs (store-detail.html) + GC6 mockup count; adaptations in §4.2. */\n.tabs {\n  display: flex; align-items: flex-end; gap: var(--space-1);\n  border-bottom: 1px solid var(--border-base);\n}\n.tab {\n  display: inline-flex; align-items: center; gap: var(--space-2);\n  margin-bottom: -1px;\n  padding: var(--space-2) var(--space-4);\n  border: 0; border-bottom: 2.5px solid transparent;\n  border-radius: var(--radius-sm) var(--radius-sm) 0 0;\n  background: none; cursor: pointer;\n  font: inherit; font-size: var(--text-sm); font-weight: 600;\n  color: var(--text-muted);\n}\n.tab:hover { color: var(--text-heading); }\n.tab:focus-visible { outline: none; box-shadow: var(--focus-ring); }\n.tab[aria-selected=\"true\"] { font-weight: 700; color: var(--text-accent); border-bottom-color: var(--accent-purple); }\n.tab-count {\n  padding: 0 var(--space-1);\n  border-radius: 999px;\n  background: var(--surface-hover);\n  font-size: var(--text-xs); font-weight: 600;\n  color: var(--text-body);\n}\n.tab-panel { padding-top: var(--space-4); }\n\n/* ── File gauge (GC12) — <FileGauge>: four stage pips + F/V search badges ─\n   A pip's SHAPE is its stage state; the tone class COLOURS the outcome through\n   `color`, which the pips inherit (badges, label and card text set their own).\n   The report card is portalled out of the gauge, so it carries the tone class\n   itself and every card rule is rooted at the card. */\n.file-gauge {\n  display: inline-flex; align-items: center; gap: var(--space-1); flex: none;\n  padding: 1px var(--space-1); margin: 0; border: 0; border-radius: var(--radius-sm);\n  background: none; font: inherit; line-height: 1; white-space: nowrap;\n  vertical-align: middle; cursor: default;\n}\n.file-gauge:focus-visible { outline: none; box-shadow: var(--focus-ring); }\n.file-gauge.tone-ok, .file-gauge-card.tone-ok { color: var(--accent-green); }\n.file-gauge.tone-working, .file-gauge-card.tone-working { color: var(--accent-purple); }\n.file-gauge.tone-failed, .file-gauge-card.tone-failed { color: var(--accent-red); }\n.file-gauge.tone-muted, .file-gauge-card.tone-muted { color: var(--text-muted); }\n\n.file-gauge-pips { display: inline-flex; gap: 2px; }\n.file-gauge-pip { display: block; flex: none; }\n.file-gauge-pip.done .dot { fill: currentColor; }\n.file-gauge-pip .ring { fill: none; stroke-width: 1.5; }\n.file-gauge-pip.todo .ring, .file-gauge-pip.active .ring, .file-gauge-pip.partial .ring,\n.file-gauge-pip.skipped .ring { stroke: var(--text-faint); }\n.file-gauge-pip.waiting .ring { stroke: var(--accent-purple); stroke-dasharray: 1.6 1.4; }\n.file-gauge-pip .fill { fill: none; stroke: currentColor; stroke-width: 1.5; }\n.file-gauge-pip .slash, .file-gauge-pip .cross { stroke: currentColor; stroke-width: 1.4; stroke-linecap: round; }\n.file-gauge-pip.skipped { color: var(--text-muted); }\n.file-gauge-pip.failed { color: var(--accent-red); }\n/* An unmeasured active stage pulses; a measured one draws its arc and holds still. */\n.file-gauge-pip.active:not(:has(.fill)) .ring { stroke: var(--accent-purple); animation: file-gauge-pulse 1.3s ease-in-out infinite; }\n@keyframes file-gauge-pulse { 50% { opacity: 0.35; } }\n@media (prefers-reduced-motion: reduce) {\n  .file-gauge-pip.active:not(:has(.fill)) .ring { animation: none; }\n}\n\n.file-gauge-badge {\n  font-size: var(--text-2xs); font-weight: 700; letter-spacing: 0.02em; line-height: 1;\n  padding: 1px 3px; border: 1px solid var(--border-base); border-radius: calc(var(--radius-sm) / 2);\n}\n.file-gauge-badge.no { color: var(--text-faint); }\n.file-gauge-badge.yes { color: var(--text-accent); border-color: var(--text-accent); }\n.file-gauge-badge.partial { color: var(--text-accent); border-color: var(--text-accent); border-style: dashed; }\n.file-gauge-label { font-size: var(--text-2xs); color: var(--text-body); }\n\n.file-gauge-card {\n  position: fixed; z-index: 400; width: 240px; box-sizing: border-box;\n  display: flex; flex-direction: column; gap: var(--space-1);\n  padding: var(--space-2) var(--space-3);\n  background: var(--bg-surface); border: 1px solid var(--border-base); border-radius: var(--radius-md);\n  box-shadow: var(--elev-dropdown);\n  font-size: var(--text-xs); line-height: var(--leading-snug);\n  white-space: normal; text-align: left; cursor: default;\n}\n.file-gauge-card-name { font-weight: 700; color: var(--text-heading); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.file-gauge-card-row { display: grid; grid-template-columns: 10px 1fr auto; align-items: center; gap: var(--space-2); }\n.file-gauge-card-stage { color: var(--text-body); }\n.file-gauge-card-row.skipped .file-gauge-card-stage { color: var(--text-muted); }\n.file-gauge-card-detail { color: var(--text-muted); font-variant-numeric: tabular-nums; }\n.file-gauge-card-hint { margin-top: var(--space-1); color: var(--text-muted); }\n"
